--rollback DELETE FROM words WHERE word IN ('different','information','danger','error','excuse','fancy','gentle','growth','improvement','material','messy','middle','normal','opinion','opposite','power','safety','secret','silly','smart','special','straight','style','usual','lie','agreement','alternative','antique','central','characteristic','commitment','component','concept','decline','depth','development','disaster','economy','fault','finance','foolish','former','incident','industry','limitation','miracle','mission','occasion','overall','pace','phase','preference','requirement','response','restriction','sample','saving','spare','status','territory','tragedy','weird','latter','obligation','regulation','transformation','transition');
